css:
/* Owner-approved card layout (2026-10-14): the familiar navy-band card, with the
   bundled app font and the legacy .print-format override that lets the content
   own the full printable width. */
@font-face { font-family: 'Card Arabic'; src: url('/assets/card/fonts/NotoSansArabic-Regular.ttf'); font-weight: normal; font-style: normal; }
@font-face { font-family: 'Card Arabic'; src: url('/assets/card/fonts/NotoSansArabic-Bold.ttf'); font-weight: bold; font-style: normal; }
@font-face { font-family: 'Noto Sans'; src: url('/assets/card/fonts/NotoSans-Regular.ttf'); font-weight: normal; font-style: normal; }
@font-face { font-family: 'Noto Sans'; src: url('/assets/card/fonts/NotoSans-Bold.ttf'); font-weight: bold; font-style: normal; }

.print-format { padding: 0 !important; margin: 0 !important; max-width: 100% !important; width: 100% !important; }
.print-format-gutter { padding: 0 !important; }

/* text-rendering auto: frappe's print bundle sets optimizeLegibility on body,
   which makes Qt draw RTL lines wider than it measures them (text crosses cell
   borders); resetting it here fixes the geometry. */
.emc { text-rendering: auto; direction: rtl; font-family: 'Noto Sans Arabic', 'Card Arabic', 'Noto Sans', 'Segoe UI', Tahoma, sans-serif; font-size: 11px; color: #1f2933; width: 100%; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
.emc table { width: 100%; border-collapse: collapse; margin: 0; }
.emc th, .emc td { word-wrap: break-word; }

.emc-lh { margin-bottom: 4mm; text-align: center; }
.emc-lh img { max-height: 22mm; max-width: 100%; }

.emc-title { background: #12355b !important; text-align: center; padding: 2.5mm; border-radius: 2mm; margin-bottom: 3mm; }
.emc-title * { color: #fff !important; }
.emc-title-ar { font-size: 18px; font-weight: bold; }
.emc-title-en { font-size: 11px; }
.emc-meta-t { width: 92% !important; margin: 1mm auto 0 !important; }
.emc-meta-t td { border: none !important; background: transparent !important; text-align: center; font-size: 11px; padding: 0 1mm; white-space: nowrap; }
.emc-badge { background: #b42318; border-radius: 2mm; padding: 0.5mm 2mm; margin-right: 2mm; font-weight: bold; }

.emc-head-outer { margin-bottom: 3mm !important; }
.emc-head-outer td.ehc { border: none !important; padding: 0 !important; vertical-align: top; }
.emc-head th, .emc-head td { border: 1px solid #cfd8e3 !important; padding: 1.5mm 2.5mm !important; text-align: right; vertical-align: middle; font-size: 11px; }
.emc-head th { background: #eef3f8 !important; color: #12355b !important; width: 12%; white-space: nowrap; font-weight: bold; }
.emc-img { width: 16%; border: 1px solid #cfd8e3 !important; text-align: center; vertical-align: middle; padding: 1mm !important; }
.emc-img img { max-width: 100%; max-height: 26mm; }

.emc-days-wrap td.emc-half { width: 50%; vertical-align: top; padding: 0 1mm !important; border: none !important; }
.emc-days { table-layout: fixed; }
.emc-days td { border: 1px solid #dfe5ec !important; padding: 0 2px !important; text-align: center; height: 6.2mm; font-size: 10px; overflow: hidden; }
.emc-days tr.emc-days-head td { background: #12355b !important; color: #fff !important; font-weight: bold; font-size: 10.5px; padding: 1.5mm 1px !important; border: 1px solid #12355b !important; }
.emc-days td.num { font-weight: bold; }
.emc-days tr.fri td { background: #fff1db !important; }
.emc-days tr.off td { color: #b42318 !important; }

.emc-totals { margin-top: 3mm !important; border-collapse: separate !important; border-spacing: 2mm 0; table-layout: fixed; }
.emc-totals td { width: 25%; border: 1.5px solid #12355b !important; border-radius: 2mm; text-align: center; padding: 2mm 1mm !important; background: #f7f9fc !important; overflow: hidden; }
.emc-totals .lbl { display: block; font-size: 11px; color: #12355b; font-weight: bold; margin-bottom: 1mm; }
.emc-totals .val { display: block; font-size: 18px; font-weight: bold; color: #1f2933; }
.emc-totals td.amount { background: #e6f4ea !important; border-color: #137333 !important; }
.emc-totals td.amount .lbl, .emc-totals td.amount .val { color: #137333; }
.emc-totals td.amount .val { font-size: 20px; }
.emc-totals-2 td { width: 50%; }

.emc-adj { margin-top: 3mm !important; table-layout: fixed; }
.emc-adj td { border: 1px solid #dfe5ec !important; padding: 1mm 2mm !important; text-align: right; font-size: 10.5px; overflow: hidden; }
.emc-adj tr.emc-adj-head td { background: #eef3f8 !important; color: #12355b !important; font-weight: bold; text-align: center; }
.emc-adj td.num { text-align: center; }
.emc-net td { width: 25%; }
.emc-net .val { font-size: 16px; }
.emc-net td.amount .val { font-size: 18px; }

.emc-sign { margin-top: 4mm !important; table-layout: fixed; }
.emc-sign td { width: 33%; text-align: center; padding: 0 6mm !important; border: none !important; }
.emc-sign .t { font-weight: bold; font-size: 12px; color: #12355b; }
.emc-sign .n { margin-top: 1mm; min-height: 4mm; }
.emc-sign .l { border-bottom: 1px solid #52606d; height: 10mm; }

html:
{%- set months = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'] -%}
{%- set days = doc.days or [] -%}
{%- set half = ((days|length) + 1) // 2 -%}
{%- set eq_type = frappe.db.get_value("Card Equipment", doc.equipment, "equipment_type") if doc.equipment else "" -%}
{%- set supplier_name = frappe.db.get_value("Supplier", doc.supplier, "supplier_name") if doc.supplier else "" -%}
{%- set customer_name = frappe.db.get_value("Customer", doc.customer, "customer_name") if doc.customer else "" -%}
{%- set supplier_side = doc.card_direction in ["مستأجَرة من مورد", "إيجار من الباطن"] -%}
{%- set customer_side = doc.card_direction in ["مؤجَّرة لعميل", "إيجار من الباطن"] -%}
<div class="emc">
  {% if letter_head %}<div class="emc-lh">{{ letter_head }}</div>{% endif %}

  <div class="emc-title">
    <div class="emc-title-ar">كارت تشغيل معدة شهري</div>
    <div class="emc-title-en">Equipment Monthly Operation Card</div>
    <table class="emc-meta-t"><tr>
      <td>رقم الكارت: <b><span dir="ltr">{{ doc.name }}</span></b></td>
      {#- no <b> here: Qt overlaps a regular+bold Arabic run pair in this cell -#}
      <td>الشهر: {{ months[(doc.month|int) - 1] if doc.month else '' }} <span dir="ltr">{{ doc.year }}</span></td>
      <td>الوردية: <b>{{ doc.shift or '' }}</b>
      {%- if doc.docstatus == 0 %} <span class="emc-badge">مسودة</span>{% elif doc.docstatus == 2 %} <span class="emc-badge">ملغي</span>{% endif -%}</td>
    </tr></table>
  </div>

  {#- no rowspan: Qt WebKit misplaces auto-layout columns next to a rowspan cell,
      so the image sits in its own cell of an outer wrapper table instead. -#}
  <table class="emc-head-outer"><tr>
    <td class="ehc">
  <table class="emc-head">
    <tr>
      <th>المعدة</th><td>{{ (doc.equipment_name or '')|e }} {% if doc.equipment %}(<span dir="ltr">{{ doc.equipment }}</span>){% endif %}</td>
      <th>المشروع</th><td>{{ (doc.project_name or doc.project or '')|e }}</td>
    </tr>
    <tr>
      <th>نوع المعدة</th><td>{{ (eq_type or '')|e }}</td>
      <th>الموقع</th><td>{{ (doc.site_location or '')|e }}</td>
    </tr>
    <tr>
      <th>الملكية</th><td>{{ doc.ownership or '' }}{% if doc.card_direction %} — {{ doc.card_direction }}{% endif %}</td>
      <th>السائق / المشغّل</th><td>{{ (doc.operator_name or '')|e }}</td>
    </tr>
    <tr>
      {% if customer_side and not supplier_side %}
      <th>العميل</th><td>{{ (customer_name or doc.customer or '')|e }}</td>
      {% else %}
      <th>المالك</th><td>{{ (supplier_name or doc.supplier or 'الشركة')|e }}</td>
      {% endif %}
      <th>الفترة</th><td><span dir="ltr">{{ frappe.utils.formatdate(doc.from_date) }} - {{ frappe.utils.formatdate(doc.to_date) }}</span></td>
    </tr>
    {% if supplier_side and customer_side %}
    <tr>
      <th>العميل</th><td colspan="3">{{ (customer_name or doc.customer or '')|e }}</td>
    </tr>
    {% endif %}
  </table>
    </td>
    {% if doc.image %}<td class="emc-img"><img src="{{ doc.image }}"></td>{% endif %}
  </tr></table>

  <table class="emc-days-wrap"><tr>
  {% for part in [days[:half], days[half:]] %}
    <td class="emc-half">
      <table class="emc-days">
        <tr class="emc-days-head">
          <td style="width:6%;">م</td>
          <td style="width:12%;">التاريخ</td>
          <td style="width:13%;">اليوم</td>
          <td style="width:12%;">الحالة</td>
          <td style="width:11%;">الساعات</td>
          <td style="width:23%;">سبب التوقف</td>
          <td style="width:23%;">ملاحظات</td>
        </tr>
        {% for r in part %}
          <tr class="{% if r.day_name == 'الجمعة' %}fri{% endif %} {% if r.day_status != 'عمل' %}off{% endif %}">
            <td>{{ r.idx }}</td>
            <td><span dir="ltr">{{ frappe.utils.formatdate(r.operation_date, 'dd-MM') }}</span></td>
            <td>{{ r.day_name or '' }}</td>
            <td>{{ r.day_status or '' }}</td>
            <td class="num">{% if (r.working_hours or 0) > 0 %}{{ '%.1f'|format(r.working_hours) }}{% else %}-{% endif %}</td>
            <td>{{ (r.idle_reason or '')|e }}</td>
            <td>{{ (r.notes or '')|e }}</td>
          </tr>
        {% endfor %}
        {% if part|length < half %}
          <tr><td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td><td></td></tr>
        {% endif %}
      </table>
    </td>
  {% endfor %}
  </tr></table>

  <table class="emc-totals"><tr>
    <td><span class="lbl">إجمالي ساعات التشغيل</span><span class="val">{{ '%.1f'|format(doc.total_working_hours or 0) }}</span></td>
    <td><span class="lbl">أيام العمل</span><span class="val">{{ doc.working_days or 0 }}</span></td>
    {% if customer_side and not supplier_side %}
    <td><span class="lbl">سعر العميل ({{ doc.customer_rate_type or '' }})</span><span class="val">{{ frappe.utils.fmt_money(doc.customer_rate or 0) }}</span></td>
    <td class="amount"><span class="lbl">القيمة الإجمالية</span><span class="val">{{ frappe.utils.fmt_money(doc.customer_amount or 0) }}</span></td>
    {% elif supplier_side %}
    <td><span class="lbl">السعر ({{ doc.rate_type or '' }})</span><span class="val">{{ frappe.utils.fmt_money(doc.rate or 0) }}</span></td>
    <td class="amount"><span class="lbl">القيمة الإجمالية</span><span class="val">{{ frappe.utils.fmt_money(doc.amount or 0) }}</span></td>
    {% else %}
    <td colspan="2"><span class="lbl">تشغيل داخلي</span><span class="val">بدون فوترة</span></td>
    {% endif %}
  </tr></table>

  {% if supplier_side and customer_side %}
  <table class="emc-totals emc-totals-2"><tr>
    <td><span class="lbl">سعر العميل ({{ doc.customer_rate_type or '' }})</span><span class="val">{{ frappe.utils.fmt_money(doc.customer_rate or 0) }}</span></td>
    <td class="amount"><span class="lbl">قيمة جانب العميل</span><span class="val">{{ frappe.utils.fmt_money(doc.customer_amount or 0) }}</span></td>
  </tr></table>
  {% endif %}

  {#- settlement per billed side = the invoice of that side: gross (the base
      line) + that side's additions - its deductions = the net the PI/SI bills
      before VAT (posting._card_lines asserts the same identity). Supplier:
      amount -> net_amount; customer: customer_amount -> customer_net_amount.
      A row without a side is a v1.1 row, counted on the supplier side
      (backfill_adjustment_side). One weight per cell: Qt overlaps a
      regular+bold Arabic run pair. -#}
  {%- set adj = doc.adjustments or [] -%}
  {%- set ns = namespace(s_add=0, s_ded=0, s_n=0, c_add=0, c_ded=0, c_n=0) -%}
  {%- for a in adj -%}
    {%- set amt = frappe.utils.flt(a.amount) -%}
    {%- if a.side == "Customer" -%}
      {%- set ns.c_n = ns.c_n + 1 -%}
      {%- if a.adjustment_type == "إضافة" %}{% set ns.c_add = ns.c_add + amt %}{% elif a.adjustment_type == "خصم" %}{% set ns.c_ded = ns.c_ded + amt %}{% endif -%}
    {%- else -%}
      {%- set ns.s_n = ns.s_n + 1 -%}
      {%- if a.adjustment_type == "إضافة" %}{% set ns.s_add = ns.s_add + amt %}{% elif a.adjustment_type == "خصم" %}{% set ns.s_ded = ns.s_ded + amt %}{% endif -%}
    {%- endif -%}
  {%- endfor %}
  {% if adj %}
  <table class="emc-adj">
    <tr class="emc-adj-head">
      <td style="width:14%;">الجهة</td>
      <td style="width:12%;">النوع</td>
      <td>البيان</td>
      <td style="width:18%;">المبلغ</td>
    </tr>
    {% for a in adj %}
    <tr>
      <td>{{ "العميل" if a.side == "Customer" else "المورد" }}</td>
      <td>{{ a.adjustment_type or '' }}</td>
      <td>{{ (a.description or a.adjustment_type_ref or '')|e }}</td>
      <td class="num"><span dir="ltr">{{ frappe.utils.fmt_money(a.amount or 0) }}</span></td>
    </tr>
    {% endfor %}
  </table>
  {% endif %}
  {% if supplier_side or ns.s_n %}
  <table class="emc-totals emc-net"><tr>
    <td><span class="lbl">إجمالي المورد</span><span class="val">{{ frappe.utils.fmt_money(doc.amount or 0) }}</span></td>
    <td><span class="lbl">إضافات المورد</span><span class="val">{{ frappe.utils.fmt_money(ns.s_add) }}</span></td>
    <td><span class="lbl">خصومات المورد</span><span class="val">{{ frappe.utils.fmt_money(ns.s_ded) }}</span></td>
    <td class="amount"><span class="lbl">صافي المورد قبل الضريبة</span><span class="val">{{ frappe.utils.fmt_money(doc.net_amount or 0) }}</span></td>
  </tr></table>
  {% endif %}
  {% if customer_side or ns.c_n %}
  <table class="emc-totals emc-net"><tr>
    <td><span class="lbl">إجمالي العميل</span><span class="val">{{ frappe.utils.fmt_money(doc.customer_amount or 0) }}</span></td>
    <td><span class="lbl">إضافات العميل</span><span class="val">{{ frappe.utils.fmt_money(ns.c_add) }}</span></td>
    <td><span class="lbl">خصومات العميل</span><span class="val">{{ frappe.utils.fmt_money(ns.c_ded) }}</span></td>
    <td class="amount"><span class="lbl">صافي العميل قبل الضريبة</span><span class="val">{{ frappe.utils.fmt_money(doc.customer_net_amount or 0) }}</span></td>
  </tr></table>
  {% endif %}

  <table class="emc-sign"><tr>
    <td><div class="t">توقيع السائق / المشغّل</div><div class="n">{% if doc.operator_name %}{{ doc.operator_name|e }}{% else %}&nbsp;{% endif %}</div><div class="l"></div></td>
    <td><div class="t">اعتماد المشرف الميداني</div><div class="n">&nbsp;</div><div class="l"></div></td>
    <td><div class="t">اعتماد مدير المشروع</div><div class="n">&nbsp;</div><div class="l"></div></td>
  </tr></table>
</div>
